/** Repository of the "audit_entries" table: reads and writes rows, and decides nothing. */
import { asc, count, eq } from 'drizzle-orm'
import { isRefusal, type Db } from '../database.js'
import { AuditEntry } from '../entities/audit-entry.js'
import { ConflictError } from '../errors.js'
import type { Page } from '../paging.js'
import { auditEntries } from '../schema.js'

/** Where audit_entries rows are kept. Services depend only on this interface. */
export interface AuditEntryRepository {
  findByEntryNo(entryNo: number): Promise<AuditEntry | null>
  list(offset?: number, limit?: number): Promise<Page<AuditEntry>>
  listByOrderId(orderId: number): Promise<AuditEntry[]>
  insert(entity: AuditEntry): Promise<AuditEntry>
  update(entity: AuditEntry): Promise<AuditEntry>
  delete(entity: AuditEntry): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: AuditEntry): unknown[] {
  return [row.entryNo]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The AuditEntry of a row Drizzle read. */
function toEntity(row: typeof auditEntries.$inferSelect): AuditEntry {
  return Object.assign(new AuditEntry(), row)
}

/** The values of a new row; those left undefined take the database's default. */
function insertValues(entity: AuditEntry): typeof auditEntries.$inferInsert {
  return {
    entryNo: entity.entryNo,
    orderId: entity.orderId,
    message: entity.message,
  }
}

/** The values a change writes: not the key, nor what the database fills. */
function updateValues(entity: AuditEntry): Partial<typeof auditEntries.$inferInsert> {
  return {
    orderId: entity.orderId,
    message: entity.message,
  }
}

/** Keeps audit_entries rows in the database, through Drizzle. It never commits: the transaction belongs to the database it was given. */
export class SqlAuditEntryRepository implements AuditEntryRepository {
  constructor(private readonly db: Db) {}

  /** The row with this primary key, or null. */
  async findByEntryNo(entryNo: number): Promise<AuditEntry | null> {
    const [row] = await this.db.select().from(auditEntries).where(eq(auditEntries.entryNo, entryNo)).limit(1)
    return row === undefined ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<AuditEntry>> {
    const rows = await this.db.select().from(auditEntries).orderBy(asc(auditEntries.entryNo)).limit(limit).offset(offset)
    const [{ total }] = await this.db.select({ total: count() }).from(auditEntries)
    return { items: rows.map(toEntity), total, offset, limit }
  }

  /** Rows with this orderId, by primary key. */
  async listByOrderId(orderId: number): Promise<AuditEntry[]> {
    return (await this.db.select().from(auditEntries).where(eq(auditEntries.orderId, orderId)).orderBy(asc(auditEntries.entryNo))).map(toEntity)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: AuditEntry): Promise<AuditEntry> {
    try {
      const [row] = await this.db.insert(auditEntries).values(insertValues(entity)).returning()
      return Object.assign(entity, toEntity(row))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('AuditEntry', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: AuditEntry): Promise<AuditEntry> {
    try {
      await this.db.update(auditEntries).set(updateValues(entity)).where(eq(auditEntries.entryNo, entity.entryNo))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('AuditEntry', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: AuditEntry): Promise<void> {
    try {
      await this.db.delete(auditEntries).where(eq(auditEntries.entryNo, entity.entryNo))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('AuditEntry', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
  }
}

/** Keeps audit_entries rows in memory, for tests and for trying the services without a database. */
export class MemoryAuditEntryRepository implements AuditEntryRepository {
  private readonly rows = new Map<string, AuditEntry>()
  private nextId = 1

  private visible(): AuditEntry[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findByEntryNo(entryNo: number): Promise<AuditEntry | null> {
    return this.visible().find((row) => row.entryNo === entryNo) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<AuditEntry>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** Rows with this orderId, by primary key. */
  async listByOrderId(orderId: number): Promise<AuditEntry[]> {
    return this.visible().filter((row) => row.orderId === orderId)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: AuditEntry): Promise<AuditEntry> {
    if (entity.entryNo === undefined) entity.entryNo = this.nextId++
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: AuditEntry): Promise<AuditEntry> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: AuditEntry): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

