/** The tables of the database, as Drizzle reads and writes them. They reflect the database: do not migrate with them. */
import { sql } from 'drizzle-orm'
import { check, foreignKey, integer, numeric, primaryKey, real, sqliteTable, text, unique } from 'drizzle-orm/sqlite-core'
import { bytes, datetime } from './column-types.js'

/** The "things" table. */
export const things = sqliteTable(
  'things',
  {
    id: integer('id').primaryKey(),
    small: integer('small').notNull(),
    big: integer('big').notNull(),
    price: numeric('price').notNull(),
    d: real('d').notNull(),
    flag: integer('flag', { mode: 'boolean' }).notNull().default(true),
    born: text('born').notNull(),
    opens: text('opens').notNull(),
    at: datetime('at').notNull(),
    changed: datetime('changed').default(sql`CURRENT_TIMESTAMP`),
    bin: bytes('bin').notNull(),
