/** The repositories of every table, and the transaction of each service operation. Each service operation runs in `transaction()`: committed when it ends, rolled back when it fails. */
import { sql } from 'drizzle-orm'
import type { Db } from './database.js'
import { MemoryAuditEntryRepository, SqlAuditEntryRepository, type AuditEntryRepository } from './repositories/audit-entry.js'
import { MemoryEmptyRepository, SqlEmptyRepository, type EmptyRepository } from './repositories/empty.js'
import { MemoryKindRepository, SqlKindRepository, type KindRepository } from './repositories/kind.js'
import { MemoryOrderRepository, SqlOrderRepository, type OrderRepository } from './repositories/order.js'
import { MemoryThingRepository, SqlThingRepository, type ThingRepository } from './repositories/thing.js'

/** What services depend on: a repository per table and a transaction. */
export interface UnitOfWork {
  readonly things: ThingRepository
  readonly kinds: KindRepository
  readonly order: OrderRepository
  readonly auditEntries: AuditEntryRepository
  readonly empties: EmptyRepository
  /** Runs `work` with the repositories of the transaction; commits when it ends, rolls back when it throws. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T>
}

/** The repositories over one database: the application's, or one of its transactions. */
export class SqlUnitOfWork implements UnitOfWork {
  readonly things: ThingRepository
  readonly kinds: KindRepository
  readonly order: OrderRepository
  readonly auditEntries: AuditEntryRepository
  readonly empties: EmptyRepository

  constructor(
    readonly db: Db,
    private readonly inTransaction = false,
  ) {
    this.things = new SqlThingRepository(db)
    this.kinds = new SqlKindRepository(db)
    this.order = new SqlOrderRepository(db)
    this.auditEntries = new SqlAuditEntryRepository(db)
    this.empties = new SqlEmptyRepository(db)
  }

  /** Runs `work` in a transaction of its own, or in the one already open. */
  async transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T> {
    if (this.inTransaction) return work(this)
    // better-sqlite3 has one connection and Drizzle's transactions on it cannot wait for promises: the
    // transaction is opened and closed here
    this.db.run(sql`BEGIN`)
    try {
      const result = await work(new SqlUnitOfWork(this.db, true))
      this.db.run(sql`COMMIT`)
      return result
    } catch (error) {
      this.db.run(sql`ROLLBACK`)
      throw error
    }
  }
}

/** The in-memory repositories, for tests and for trying the services without a database. */
export class MemoryUnitOfWork implements UnitOfWork {
  readonly things = new MemoryThingRepository()
  readonly kinds = new MemoryKindRepository()
  readonly order = new MemoryOrderRepository()
  readonly auditEntries = new MemoryAuditEntryRepository()
  readonly empties = new MemoryEmptyRepository()

  /** Memory has no transactions: changes are kept as they are made. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T> {
    return work(this)
  }
}

