/** Rows for the tests: valid values for every column, and the rows they point to. */
import { AuditEntry } from '../src/entities/audit-entry.js'
import { Empty } from '../src/entities/empty.js'
import { Kind } from '../src/entities/kind.js'
import { Order } from '../src/entities/order.js'
import { Thing } from '../src/entities/thing.js'
import type { UnitOfWork } from '../src/unit-of-work.js'

/** A valid Thing that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newThing(n = 1, values: Partial<Thing> = {}): Thing {
  return Object.assign(new Thing(), { small: n, big: n, price: `${n % 10000}.50`, d: n + 0.5, flag: true, born: `2026-01-${String((n % 28) + 1).padStart(2, '0')}`, opens: `12:${String(n % 60).padStart(2, '0')}:00`, at: new Date(Date.UTC(2026, 0, (n % 28) + 1, 12, 0, 0)), bin: Buffer.from([n % 256]), data: { n }, code: String(n).padStart(5, '0').slice(-5), note: `note-${n}` }, values)
}

/** A stored Thing. */
export async function addThing(uow: UnitOfWork, n = 1): Promise<Thing> {
  return uow.things.insert(newThing(n))
}

/** A valid Kind that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newKind(n = 1, values: Partial<Kind> = {}): Kind {
  return Object.assign(new Kind(), { code: `code-${n}`, day: `2026-01-${String((n % 28) + 1).padStart(2, '0')}`, label: `label-${n}` }, values)
}

/** A stored Kind. */
export async function addKind(uow: UnitOfWork, n = 1): Promise<Kind> {
  return uow.kinds.insert(newKind(n))
}

/** A valid Order that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newOrder(n = 1, values: Partial<Order> = {}): Order {
  return Object.assign(new Order(), { user: `user-${n}`, group: n, customerName: `customername-${n}`, class_: `class-${n}`, metadata: `metadata-${n}`, date: `2026-01-${String((n % 28) + 1).padStart(2, '0')}`, time: `12:${String(n % 60).padStart(2, '0')}:00`, text: `text-${n}`, list: `list-${n}`, str: `str-${n}`, int: n, dueDate: `2026-01-${String((n % 28) + 1).padStart(2, '0')}`, closesAt: `12:${String(n % 60).padStart(2, '0')}:00`, kindCode: null, kindDay: null, thingId: null, parentId: null }, values)
}

/** A stored Order. */
export async function addOrder(uow: UnitOfWork, n = 1): Promise<Order> {
  return uow.order.insert(newOrder(n))
}

/** A valid AuditEntry that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newAuditEntry(n = 1, values: Partial<AuditEntry> = {}): AuditEntry {
  return Object.assign(new AuditEntry(), { message: `message-${n}` }, values)
}

/** A stored AuditEntry, with the rows it points to. */
export async function addAuditEntry(uow: UnitOfWork, n = 1): Promise<AuditEntry> {
  const parent0 = await addOrder(uow, n)
  return uow.auditEntries.insert(newAuditEntry(n, { orderId: parent0.id }))
}

/** A valid Empty that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newEmpty(n = 1, values: Partial<Empty> = {}): Empty {
  return Object.assign(new Empty(), { note: `note-${n}` }, values)
}

/** A stored Empty. */
export async function addEmpty(uow: UnitOfWork, n = 1): Promise<Empty> {
  return uow.empties.insert(newEmpty(n))
}

