/** Tests of the "things" table. */
import { describe, expect, it } from 'vitest'
import { NotFoundError, ValidationFailedError } from '../src/errors.js'
import { ThingService } from '../src/services/thing.js'
import { MemoryUnitOfWork } from '../src/unit-of-work.js'
import { useTestDatabase } from './database.js'
import { addThing, newThing } from './factories.js'

/** The repositories over the test database, opened empty for every test */
const sqlUow = useTestDatabase()

describe('things repository', () => {
  it('is stored and read back', async () => {
    const uow = sqlUow()
    const stored = await addThing(uow, 1)
    const found = await uow.things.findById(stored.id)
    expect(found).not.toBeNull()
    expect(found!.id).toEqual(stored.id)
  })

  it('lists rows by key', async () => {
    const uow = sqlUow()
    await addThing(uow, 1)
    await addThing(uow, 2)
    const page = await uow.things.list(0, 1)
    expect(page.total).toBe(2)
    expect(page.items).toHaveLength(1)
  })

  it('stores the changes', async () => {
    const uow = sqlUow()
    const stored = await addThing(uow, 1)
    stored.note = 'changed'
    await uow.things.update(stored)
    const found = await uow.things.findById(stored.id)
    expect(found?.note).toBe('changed')
  })

  it('is deleted', async () => {
    const uow = sqlUow()
    const stored = await addThing(uow, 1)
    await uow.things.delete(stored)
    expect(await uow.things.findById(stored.id)).toBeNull()
  })
})

describe('ThingService', () => {
  it('creates a valid row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ThingService(uow)
    const n = 100
    const created = await service.createThing(newThing(1))
    const found = await service.getThing(created.id)
    expect(found.id).toEqual(created.id)
  })

  it('refuses a missing value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ThingService(uow)
    const n = 100
    const error: unknown = await service.createThing(newThing(1, { small: null as never })).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toEqual(['small'])
  })

  it('says when a row is missing', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ThingService(uow)
    await expect(service.getThing(999999)).rejects.toBeInstanceOf(NotFoundError)
  })

  it('changes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ThingService(uow)
    const n = 100
    const created = await service.createThing(newThing(1))
    const updated = await service.updateThing(created.id, { note: 'changed' })
    expect(updated.note).toBe('changed')
  })

  it('deletes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new ThingService(uow)
    const n = 100
    const created = await service.createThing(newThing(1))
    await service.deleteThing(created.id)
    await expect(service.getThing(created.id)).rejects.toBeInstanceOf(NotFoundError)
  })
})

